import React from 'react';
import { clsx } from 'clsx';

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  variant?: 'low' | 'medium' | 'high' | 'info' | 'success' | 'slate';
  icon?: React.ReactNode;
}

export const Badge: React.FC<BadgeProps> = ({ children, variant = 'info', icon, className, ...props }) => {
  const variants = {
    high: 'bg-rose-950/80 text-rose-300 border-rose-800/60',
    medium: 'bg-amber-950/80 text-amber-300 border-amber-800/60',
    low: 'bg-emerald-950/80 text-emerald-300 border-emerald-800/60',
    info: 'bg-indigo-950/80 text-indigo-300 border-indigo-800/60',
    success: 'bg-teal-950/80 text-teal-300 border-teal-800/60',
    slate: 'bg-slate-800/80 text-slate-300 border-slate-700/60'
  };

  return (
    <span
      className={clsx(
        'inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-semibold border',
        variants[variant],
        className
      )}
      {...props}
    >
      {icon && <span aria-hidden="true">{icon}</span>}
      <span>{children}</span>
    </span>
  );
};
