import { runUnitTests } from './unitTests';
import { runSecurityTests } from './securityTests';
import { runAccessibilityTests } from './accessibilityTests';

export function executeFullTestSuite(): {
  totalPassed: number;
  totalFailed: number;
  allLogs: string[];
} {
  const unit = runUnitTests();
  const sec = runSecurityTests();
  const a11y = runAccessibilityTests();

  const totalPassed = unit.passed + sec.passed + a11y.passed;
  const totalFailed = unit.failed + sec.failed + a11y.failed;
  const allLogs = [...unit.logs, ...sec.logs, ...a11y.logs];

  console.log(`=== LEXORA TEST SUITE REPORT ===`);
  console.log(`Passed: ${totalPassed} | Failed: ${totalFailed}`);
  allLogs.forEach((log) => console.log(log));

  return { totalPassed, totalFailed, allLogs };
}
