import React, { useState } from 'react';
import { Send, HelpCircle, Sparkles, ExternalLink } from 'lucide-react';
import { UploadedDocument } from '../../types/document';
import { QAPair } from '../../types/qa';
import { askGroundedLegalQuestion } from '../../services/ai/groundedQAEngine';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Badge } from '../ui/Badge';

export interface GroundedQAViewProps {
  document: UploadedDocument;
  onSelectCitation: (range: { startChar: number; endChar: number; pageNumber: number }) => void;
}

const PRESET_QUESTIONS = [
  'What happens if I terminate this agreement early?',
  'Are there any automatic renewal terms or notice deadlines?',
  'Who owns the intellectual property and created work product?',
  'What are my exact payment and fee obligations?',
  'Are there non-compete or non-solicitation restrictions?',
  'Which clauses should I explicitly ask a lawyer about?'
];

export const GroundedQAView: React.FC<GroundedQAViewProps> = ({ document, onSelectCitation }) => {
  const [qaList, setQaList] = useState<QAPair[]>([]);
  const [inputQuery, setInputQuery] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleAsk = async (queryText: string) => {
    if (!queryText.trim() || isLoading) return;

    setIsLoading(true);
    setInputQuery('');

    try {
      const resultPair = await askGroundedLegalQuestion(document, queryText, qaList);
      setQaList((prev) => [resultPair, ...prev]);
    } catch (err) {
      console.error('Q&A error', err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Q&A Header */}
      <div className="glass-panel p-4 rounded-xl border border-slate-800 flex items-center justify-between">
        <div>
          <h3 className="text-lg font-bold text-white flex items-center gap-2">
            <HelpCircle className="h-5 w-5 text-indigo-400" />
            Grounded AI Legal Assistant
          </h3>
          <p className="text-xs text-slate-400">
            Answers are grounded strictly in the provided document with clickable source citations.
          </p>
        </div>
        <Badge variant="info" icon={<Sparkles className="h-3.5 w-3.5" />}>
          Anti-Hallucination RAG
        </Badge>
      </div>

      {/* Preset Questions Bar */}
      <div className="space-y-2">
        <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider block">
          Recommended Legal Questions:
        </label>
        <div className="flex flex-wrap gap-2">
          {PRESET_QUESTIONS.map((q, i) => (
            <button
              key={i}
              onClick={() => handleAsk(q)}
              disabled={isLoading}
              className="text-xs px-3 py-1.5 rounded-lg bg-slate-900/80 text-slate-300 border border-slate-800 hover:border-indigo-500/50 hover:bg-indigo-950/40 hover:text-white transition-all text-left disabled:opacity-50"
            >
              {q}
            </button>
          ))}
        </div>
      </div>

      {/* Query Input Box */}
      <form
        onSubmit={(e) => {
          e.preventDefault();
          handleAsk(inputQuery);
        }}
        className="flex gap-2"
      >
        <input
          type="text"
          placeholder="Ask a question about this legal document..."
          value={inputQuery}
          onChange={(e) => setInputQuery(e.target.value)}
          className="flex-1 bg-slate-900 border border-slate-800 rounded-xl px-4 py-3 text-sm text-slate-100 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-indigo-500"
        />
        <Button
          type="submit"
          variant="primary"
          isLoading={isLoading}
          leftIcon={<Send className="h-4 w-4" />}
        >
          Ask
        </Button>
      </form>

      {/* QA History Stream */}
      <div className="space-y-4">
        {qaList.map((qa) => {
          const isGrounded = qa.groundingStatus === 'Grounded';

          return (
            <Card key={qa.id} className="space-y-4 border-l-4 border-l-indigo-500">
              <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                <span className="text-sm font-bold text-indigo-300">Q: {qa.question}</span>
                <Badge variant={isGrounded ? 'success' : 'medium'}>
                  {qa.groundingStatus}
                </Badge>
              </div>

              {/* Answer Text */}
              <div className="text-xs text-slate-200 leading-relaxed bg-slate-950/60 p-3 rounded-lg border border-slate-800/80">
                <span className="text-[10px] text-indigo-400 font-bold block mb-1 uppercase tracking-wider">
                  AI Interpretation (Grounded):
                </span>
                {qa.answer}
              </div>

              {/* Source Citations */}
              {qa.citations.length > 0 && (
                <div className="space-y-2 pt-1">
                  <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider block">
                    Document Source Evidence:
                  </span>
                  <div className="space-y-2">
                    {qa.citations.map((cit) => (
                      <div
                        key={cit.id}
                        className="bg-slate-900 p-3 rounded-lg border border-slate-800 text-xs flex items-center justify-between gap-3"
                      >
                        <div className="space-y-1">
                          <span className="font-bold text-amber-300 block">
                            {cit.sectionTitle} (Page {cit.pageNumber})
                          </span>
                          <p className="text-slate-400 font-mono text-[11px] truncate max-w-md">
                            "{cit.snippet}"
                          </p>
                        </div>

                        <button
                          onClick={() =>
                            onSelectCitation({
                              startChar: cit.startChar,
                              endChar: cit.endChar,
                              pageNumber: cit.pageNumber
                            })
                          }
                          className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg bg-indigo-950 text-indigo-300 border border-indigo-800 hover:bg-indigo-900 transition-colors text-xs font-semibold flex-shrink-0"
                        >
                          <span>Jump to Page {cit.pageNumber}</span>
                          <ExternalLink className="h-3 w-3" />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </Card>
          );
        })}
      </div>
    </div>
  );
};
