import React, { useState, useEffect, useRef } from 'react';
import { FileText, Search, ZoomIn, ZoomOut, Bookmark } from 'lucide-react';
import { UploadedDocument } from '../../types/document';
import { Button } from '../ui/Button';

export interface DocumentViewerProps {
  document: UploadedDocument;
  activeCitationRange?: { startChar: number; endChar: number; pageNumber?: number } | null;
}

export const DocumentViewer: React.FC<DocumentViewerProps> = ({ document, activeCitationRange }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [zoomLevel, setZoomLevel] = useState(100);
  const containerRef = useRef<HTMLDivElement>(null);
  const highlightedRef = useRef<HTMLSpanElement>(null);

  // Auto scroll to active citation when clicked
  useEffect(() => {
    if (activeCitationRange && highlightedRef.current) {
      highlightedRef.current.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }, [activeCitationRange]);

  const renderDocumentContent = () => {
    const text = document.rawText;

    if (!activeCitationRange) {
      if (!searchQuery.trim()) {
        return <div className="whitespace-pre-wrap leading-relaxed">{text}</div>;
      }

      // Highlight search query occurrences
      const parts = text.split(new RegExp(`(${escapeRegExp(searchQuery)})`, 'gi'));
      return (
        <div className="whitespace-pre-wrap leading-relaxed">
          {parts.map((part, i) =>
            part.toLowerCase() === searchQuery.toLowerCase() ? (
              <mark key={i} className="bg-indigo-500/50 text-white rounded px-1 font-semibold">
                {part}
              </mark>
            ) : (
              part
            )
          )}
        </div>
      );
    }

    // Render text with specific active citation highlight
    const start = Math.max(0, activeCitationRange.startChar);
    const end = Math.min(text.length, activeCitationRange.endChar);

    const before = text.substring(0, start);
    const citedText = text.substring(start, end);
    const after = text.substring(end);

    return (
      <div className="whitespace-pre-wrap leading-relaxed">
        {before}
        <span
          ref={highlightedRef}
          className="citation-highlight ring-2 ring-amber-400 font-medium"
        >
          {citedText}
        </span>
        {after}
      </div>
    );
  };

  return (
    <div className="glass-panel rounded-2xl border border-slate-800 flex flex-col h-full overflow-hidden">
      {/* Viewer Header Controls */}
      <div className="p-3 bg-slate-900/90 border-b border-slate-800 flex flex-wrap items-center justify-between gap-3 text-xs">
        <div className="flex items-center gap-2 font-bold text-slate-200">
          <FileText className="h-4 w-4 text-indigo-400" />
          <span className="truncate max-w-[200px]">{document.filename}</span>
          <span className="px-2 py-0.5 rounded-full bg-slate-800 text-slate-400 font-mono">
            {document.pageCount} {document.pageCount === 1 ? 'page' : 'pages'}
          </span>
        </div>

        {/* Search Bar */}
        <div className="relative flex-1 max-w-xs">
          <Search className="h-3.5 w-3.5 absolute left-2.5 top-2.5 text-slate-400" />
          <input
            type="text"
            placeholder="Search document text..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-slate-950 border border-slate-800 rounded-lg pl-8 pr-3 py-1.5 text-xs text-slate-100 placeholder-slate-500 focus:outline-none focus:ring-1 focus:ring-indigo-500"
          />
        </div>

        {/* Zoom Controls */}
        <div className="flex items-center gap-1 bg-slate-950 border border-slate-800 rounded-lg p-1">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setZoomLevel(Math.max(80, zoomLevel - 10))}
            className="p-1 h-6 w-6"
            title="Zoom Out"
          >
            <ZoomOut className="h-3.5 w-3.5" />
          </Button>
          <span className="text-[10px] text-slate-400 w-8 text-center">{zoomLevel}%</span>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setZoomLevel(Math.min(150, zoomLevel + 10))}
            className="p-1 h-6 w-6"
            title="Zoom In"
          >
            <ZoomIn className="h-3.5 w-3.5" />
          </Button>
        </div>
      </div>

      {/* Document Text Body */}
      <div
        ref={containerRef}
        style={{ fontSize: `${(14 * zoomLevel) / 100}px` }}
        className="p-6 overflow-y-auto flex-1 font-mono text-slate-300 bg-slate-950/60 selection:bg-amber-500 selection:text-black"
        tabIndex={0}
        aria-label="Legal document text viewer"
      >
        {renderDocumentContent()}
      </div>

      {/* Citation Active Banner */}
      {activeCitationRange && (
        <div className="p-2.5 bg-amber-950/50 border-t border-amber-800/60 text-amber-200 text-xs flex items-center justify-between px-4">
          <span className="flex items-center gap-2">
            <Bookmark className="h-3.5 w-3.5 text-amber-400" />
            Jumping to cited text section (Page {activeCitationRange.pageNumber || 1})
          </span>
          <span className="text-[10px] bg-amber-900/60 px-2 py-0.5 rounded font-mono">
            Chars {activeCitationRange.startChar}-{activeCitationRange.endChar}
          </span>
        </div>
      )}
    </div>
  );
};

function escapeRegExp(string: string) {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
