import React, { useState } from 'react';
import { GitCompare } from 'lucide-react';
import { UploadedDocument } from '../../types/document';
import { ComparisonResult, DiffCategory } from '../../types/comparison';
import { MockAIProvider } from '../../services/ai/mockProvider';
import { Card } from '../ui/Card';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';

export interface ComparisonViewProps {
  currentDocument: UploadedDocument | null;
  onSelectSampleDemo: (type: 'saas_v1') => void;
}

export const ComparisonView: React.FC<ComparisonViewProps> = () => {
  const [comparisonResult, setComparisonResult] = useState<ComparisonResult | null>(null);
  const [activeCategory, setActiveCategory] = useState<DiffCategory>('all');
  const [isComparing, setIsComparing] = useState(false);

  const handleRunComparison = async (docA: UploadedDocument, docB: UploadedDocument) => {
    setIsComparing(true);
    try {
      const provider = new MockAIProvider();
      const result = await provider.compareDocuments(docA, docB);
      setComparisonResult(result);
    } catch (err) {
      console.error('Comparison error', err);
    } finally {
      setIsComparing(false);
    }
  };

  const handleDemoComparison = async () => {
    const { getSampleDocument } = await import('../../utils/sampleDocuments');
    const docA = getSampleDocument('saas_v1');
    const docB = getSampleDocument('saas_v2');
    handleRunComparison(docA, docB);
  };

  const filteredDiffs = comparisonResult
    ? comparisonResult.differences.filter((d) => activeCategory === 'all' || d.category === activeCategory)
    : [];

  return (
    <div className="space-y-6 max-w-6xl mx-auto">
      {/* Header */}
      <div className="glass-panel p-6 rounded-2xl border border-slate-800 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h3 className="text-xl font-extrabold text-white flex items-center gap-2">
            <GitCompare className="h-6 w-6 text-purple-400" />
            Side-by-Side Contract Comparison
          </h3>
          <p className="text-xs text-slate-400">
            Compare Contract Version A vs Version B to identify structural diffs in liability, termination, and payment terms.
          </p>
        </div>

        <Button
          variant="primary"
          onClick={handleDemoComparison}
          isLoading={isComparing}
          leftIcon={<GitCompare className="h-4 w-4" />}
        >
          Run Demo Comparison (SaaS V1 vs V2)
        </Button>
      </div>

      {/* Comparison Results */}
      {comparisonResult ? (
        <div className="space-y-6">
          {/* Summary Box */}
          <Card className="space-y-3 bg-purple-950/20 border-purple-900/40">
            <div className="flex items-center justify-between">
              <h4 className="text-sm font-bold text-purple-300">Comparison Executive Summary</h4>
              <Badge variant="high">{comparisonResult.highRiskCount} High Attention Changes</Badge>
            </div>
            <p className="text-xs text-slate-200 leading-relaxed">{comparisonResult.overallSummary}</p>
          </Card>

          {/* Filter Bar */}
          <div className="flex flex-wrap gap-2">
            {(['all', 'obligations', 'financial', 'termination', 'privacy', 'liability'] as DiffCategory[]).map(
              (cat) => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all ${
                    activeCategory === cat
                      ? 'bg-purple-600 text-white border-purple-500'
                      : 'bg-slate-900 text-slate-400 border-slate-800 hover:text-slate-200'
                  }`}
                >
                  {cat.replace(/_/g, ' ').toUpperCase()}
                </button>
              )
            )}
          </div>

          {/* Differences Matrix */}
          <div className="space-y-4">
            {filteredDiffs.map((diff) => (
              <Card key={diff.id} className="space-y-4 border-l-4 border-l-purple-500">
                <div className="flex flex-wrap items-center justify-between gap-2 border-b border-slate-800 pb-3">
                  <div className="flex items-center gap-2">
                    <Badge variant={diff.changeType === 'added' ? 'success' : diff.changeType === 'removed' ? 'high' : 'medium'}>
                      {diff.changeType.toUpperCase()}
                    </Badge>
                    <h4 className="text-base font-bold text-slate-100">{diff.title}</h4>
                  </div>
                  <Badge variant={diff.severity}>{diff.severity.toUpperCase()} IMPACT</Badge>
                </div>

                {/* Side by side diff boxes */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs font-mono">
                  {diff.oldText && (
                    <div className="bg-slate-950 p-3 rounded-lg border border-rose-900/40 text-rose-200">
                      <span className="text-[10px] text-rose-400 font-sans block mb-1 font-bold uppercase">
                        Version A (Old Provision):
                      </span>
                      "{diff.oldText}"
                    </div>
                  )}

                  {diff.newText && (
                    <div className="bg-slate-950 p-3 rounded-lg border border-emerald-900/40 text-emerald-200">
                      <span className="text-[10px] text-emerald-400 font-sans block mb-1 font-bold uppercase">
                        Version B (New Provision):
                      </span>
                      "{diff.newText}"
                    </div>
                  )}
                </div>

                {/* Explanations */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">
                  <div className="bg-slate-900/60 p-3 rounded-lg border border-slate-800">
                    <span className="font-bold text-slate-300 block mb-1">What Changed:</span>
                    <p className="text-slate-300 leading-relaxed">{diff.whatChanged}</p>
                  </div>

                  <div className="bg-purple-950/40 p-3 rounded-lg border border-purple-900/50">
                    <span className="font-bold text-purple-300 block mb-1">Why It May Matter:</span>
                    <p className="text-purple-200 leading-relaxed">{diff.whyItMayMatter}</p>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        </div>
      ) : (
        <div className="p-12 text-center glass-panel rounded-2xl border border-dashed border-slate-800 space-y-4">
          <GitCompare className="h-12 w-12 text-purple-400 mx-auto" />
          <h4 className="text-lg font-bold text-white">Compare Two Versions of an Agreement</h4>
          <p className="text-xs text-slate-400 max-w-md mx-auto">
            Click the button above to launch a side-by-side comparison between SaaS Agreement V1 and SaaS Agreement V2.
          </p>
        </div>
      )}
    </div>
  );
};
